from collections import deque
def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j] and not seen[i][j]:
                comp=[(i,j)]; seen[i][j]=True; q=deque([(i,j)])
                while q:
                    y,x=q.popleft()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; comp.append((ny,nx)); q.append((ny,nx))
                # BFS depth from outside
                depth={}; dq=deque()
                for y,x in comp:
                    if y==0 or x==0 or y==H-1 or x==W-1 or any(g[y+dy][x+dx]==0 for dy,dx in((1,0),(-1,0),(0,1),(0,-1))):
                        depth[(y,x)]=0; dq.append((y,x))
                md=0
                while dq:
                    y,x=dq.popleft()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) in set(comp) and (ny,nx) not in depth:
                            depth[(ny,nx)]=depth[(y,x)]+1; md=max(md,depth[(ny,nx)]); dq.append((ny,nx))
                byd={d_: g[y][x] for (y,x),d_ in depth.items()}
                D=md+1
                mp={d: byd[D-1-d] for d in byd}
                for (y,x),d_ in depth.items():
                    out[y][x]=mp[d_]
    return out
