from collections import deque, defaultdict
def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    seen=[[False]*W for _ in range(H)]
    for si in range(H):
        for sj in range(W):
            if g[si][sj] and not seen[si][sj]:
                comp=[(si,sj)]; seen[si][sj]=True; q=deque([(si,sj)])
                while q:
                    y,x=q.popleft()
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx] and not seen[ny][nx]:
                            seen[ny][nx]=True; comp.append((ny,nx)); q.append((ny,nx))
                cells=set(comp)
                adj=defaultdict(set)
                for y,x in comp:
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and (ny,nx) in cells and g[ny][nx]!=g[y][x]:
                            adj[g[y][x]].add(g[ny][nx])
                dep={}
                dq=deque()
                for y,x in comp:
                    c=g[y][x]
                    if c not in dep and (y==0 or x==0 or y==H-1 or x==W-1 or any(g[y+dy][x+dx]==0 for dy,dx in((1,0),(-1,0),(0,1),(0,-1)))):
                        dep[c]=0; dq.append(c)
                while dq:
                    c=dq.popleft()
                    for c2 in adj[c]:
                        if c2 not in dep:
                            dep[c2]=dep[c]+1; dq.append(c2)
                D=max(dep.values())+1
                order=sorted(dep,key=lambda c:dep[c])
                mp={c:order[D-1-dep[c]] for c in dep}
                for y,x in comp:
                    out[y][x]=mp[g[y][x]]
    return out
